import{_ as n,o as i,c as r,a2 as t}from"./chunks/framework.CqpfiAoK.js";const o=JSON.parse('{"title":"Einheitliche Einteilung der Kultivierungsreiche","description":"","frontmatter":{},"headers":[],"relativePath":"de/14-修炼境界统一划分.md","filePath":"de/14-修炼境界统一划分.md","lastUpdated":null}'),s={name:"de/14-修炼境界统一划分.md"};function d(h,e,u,a,c,l){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="einheitliche-einteilung-der-kultivierungsreiche" tabindex="-1">Einheitliche Einteilung der Kultivierungsreiche <a class="header-anchor" href="#einheitliche-einteilung-der-kultivierungsreiche" aria-label="Permalink to &quot;Einheitliche Einteilung der Kultivierungsreiche&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projekt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>14</td></tr><tr><td>Modul</td><td>Kosmische Gesetze und Kultivierungssysteme</td></tr><tr><td>Schlüsselwörter</td><td>Reicheinteilung, Einheitsstandard, Neun Reiche, Systemübergreifender Vergleich, Anker-Zertifizierung</td></tr></tbody></table><h2 id="i-notwendigkeit-der-einheitlichen-reicheinteilung" tabindex="-1">I. Notwendigkeit der einheitlichen Reicheinteilung <a class="header-anchor" href="#i-notwendigkeit-der-einheitlichen-reicheinteilung" aria-label="Permalink to &quot;I. Notwendigkeit der einheitlichen Reicheinteilung&quot;">​</a></h2><p>Vor der Gründung der Anker-Symbiotischen Zivilisation existierten im Heng Yuan Zhou Tausende von Kultivierungssystemen, und jedes System hatte seinen eigenen unabhängigen Standard für die Reicheinteilung. Dieses chaotische Reichssystem führte zu einer Reihe von Problemen: Die Kraft zwischen Kultivierenden verschiedener Systeme war schwer zu vergleichen, der systemübergreifende Austausch und die Zusammenarbeit fehlten an einer gemeinsamen Sprache, die Ressourcenallokation und die Bewertung des sozialen Status fehlten an einer einheitlichen Grundlage, und es trat sogar das schwerwiegende ungerechte Phänomen &quot;gleiches Reich, unterschiedliche Kraft&quot; auf.</p><p>Nach der Gründung der Anker-Symbiotischen Zivilisation wurde zur Lösung dieses Problems unter der Leitung des &quot;Komitees für Kultivierungsstandards&quot; unter dem Republikanischen Parlament aller Rassen, in Zusammenarbeit mit den repräsentativen Kultivierenden der dreihundert Systeme, nach langjähriger Forschung und Argumentation dieser &quot;Standard für die einheitliche Einteilung der Kultivierungsreiche&quot; erarbeitet. Dieser Standard basiert nicht auf den Reichsnamen irgendeines einzelnen Systems, sondern nimmt vier Dimensionen als Kernindikatoren: die Tiefe des Verständnisses des Kultivierenden für die ursprünglichen Gesetze des Universums, die Präzision der Energiekontrolle, den Grad der Bewusstseinsentwicklung und den Grad des Beitrags zum symbiotischen Netzwerk, und errichtet ein systemübergreifend allgemeines System der Reicheinteilung.</p><p>Das Kernprinzip der einheitlichen Reicheinteilung ist &quot;Substanz vor Namen&quot;: Unabhängig davon, welches System der Kultivierende verwendet oder welchen Reichsnamen er hat, solange seine Substanz die entsprechende Stufe des Einheitsstandards erreicht, wird er als dieses Reich anerkannt. Dieses Prinzip gewährleistet die Gerechtigkeit und Objektivität der Reichsbewertung.</p><h2 id="ii-ubersicht-der-neun-reiche" tabindex="-1">II. Übersicht der Neun Reiche <a class="header-anchor" href="#ii-ubersicht-der-neun-reiche" aria-label="Permalink to &quot;II. Übersicht der Neun Reiche&quot;">​</a></h2><p>Der Standard für die einheitliche Reicheinteilung unterteilt den Evolutionsprozess des Kultivierenden in neun Reiche, von niedrig nach hoch in der Reihenfolge:</p><table tabindex="0"><thead><tr><th>Reichsnummer</th><th>Reichsname</th><th>Kernmerkmal</th><th>Ungefähre Entsprechung zu den Reichen der Drei Ursprungsgrundlagen</th><th>Soziale Rolle</th></tr></thead><tbody><tr><td>Erstes Reich</td><td>Reich der Energiewahrnehmung</td><td>Nimmt anfänglich die Existenz von kosmischer Energie und Gesetzen wahr, beginnt mit formeller Kultivierung</td><td>Erste Einsicht / Lebenswahrnehmung / Raumerkennung</td><td>Anfänger</td></tr><tr><td>Zweites Reich</td><td>Reich der Energiekondensation</td><td>Kann Energie stabil absorbieren und kondensieren, baut einen grundlegenden Innenkreislauf auf</td><td>Deduktion / Kreislauf / Raumsteuerung</td><td>Anfänglicher Kultivierender</td></tr><tr><td>Drittes Reich</td><td>Reich der Energietransformation</td><td>Die Energienreinigung erreicht ein hohes Niveau, kann Energie in verschiedene Anwendungen umwandeln</td><td>Iteration / Kontinuierliches Leben / Raumtransformation</td><td>Mittlerer Kultivierender</td></tr><tr><td>Viertes Reich</td><td>Reich der Rechtsenergie</td><td>Beginnt, Gesetze zu verstehen und zu steuern, Energie und Gesetze verschmelzen zunächst</td><td>Fusion / Lebenstransformation / Rechtsraum</td><td>Fortgeschrittener Kultivierender</td></tr><tr><td>Fünftes Reich</td><td>Reich der Dao-Energie</td><td>Hat ein tiefes Verständnis für die Gesetze eines bestimmten Bereichs, bildet einen persönlichen &quot;Dao&quot;</td><td>Ursprung / Ursprungsleben / Ursprungsraum</td><td>Kultivierender auf Meisterniveau</td></tr><tr><td>Sechstes Reich</td><td>Reich der Vereinigung mit dem Dao</td><td>Der persönliche Dao und die ursprünglichen Gesetze des Universums verschmelzen tief, jede Geste entspricht dem Dao</td><td>Übertrifft das Fünfte Reich eines einzelnen Systems</td><td>Kultivierender auf Großmeisterniveau</td></tr><tr><td>Siebtes Reich</td><td>Reich der Grenzüberschreitung</td><td>Kann die Grenzen der Ebenengesetze durchbrechen, stabile operationen zwischen Ebenen durchführen</td><td>—</td><td>Mächtiger auf Ebenenniveau</td></tr><tr><td>Achtes Reich</td><td>Reich der Schöpfung</td><td>Kann vollständige Welten und Gesetzessysteme in isolierten Räumen schaffen</td><td>—</td><td>Mächtiger auf Weltniveau</td></tr><tr><td>Neuntes Reich</td><td>Reich des Ursprungs</td><td>Berührt den Ursprung des Universums, kann an der Feinabstimmung und Optimierung der kosmischen Gesetze teilnehmen</td><td>—</td><td>Mächtiger auf kosmischem Niveau</td></tr></tbody></table><p>Unter den neun Reichen sind das Erste bis Fünfte Reich die &quot;Fünf Reiche der gewöhnlichen Kultivierung&quot;, die die meisten Kultivierenden durch Anstrengung erreichen können; das Sechste bis Neunte Reich sind die &quot;Vier Reiche der heiligen Kultivierung&quot;, die extrem hohes Talent, Gelegenheit und Anstrengung erfordern, und der Durchbruch jedes Reichs ist ein kosmisches Großereignis.</p><h2 id="iii-detaillierte-standards-jedes-reichs" tabindex="-1">III. Detaillierte Standards jedes Reichs <a class="header-anchor" href="#iii-detaillierte-standards-jedes-reichs" aria-label="Permalink to &quot;III. Detaillierte Standards jedes Reichs&quot;">​</a></h2><h3 id="_3-1-erstes-reich-reich-der-energiewahrnehmung" tabindex="-1">3.1 Erstes Reich: Reich der Energiewahrnehmung <a class="header-anchor" href="#_3-1-erstes-reich-reich-der-energiewahrnehmung" aria-label="Permalink to &quot;3.1 Erstes Reich: Reich der Energiewahrnehmung&quot;">​</a></h3><p>Das Reich der Energiewahrnehmung ist der Ausgangspunkt der Kultivierung, und sein Kern ist die &quot;Wahrnehmung&quot;. Die Standards für das Erreichen des Reichs der Energiewahrnehmung umfassen:</p><ul><li>Kann die im Universum freie Energie (Geistenergie, Gesetzeskraft usw.) stabil wahrnehmen</li><li>Kann durch grundlegende Kultivierungsmethoden eine geringe Menge Energie in den Körper absorbieren</li><li>Baut ein anfängliches Energiewahrnehmungsbewusstsein auf, kann verschiedene Arten von Energie unterscheiden</li><li>Die Körperqualität erfährt eine anfängliche Verbesserung durch die Energieinfiltration</li></ul><p>Die Kultivierenden des Reichs der Energiewahrnehmung sind &quot;Anfänger&quot; in der Gesellschaft, und ihre Hauptaufgabe ist es, die Grundlage zu festigen und das für sie geeignete Kultivierungssystem zu finden. Der Durchbruch des Reichs der Energiewahrnehmung erfordert in der Regel einige Wochen bis einige Monate formelle Kultivierung.</p><h3 id="_3-2-zweites-reich-reich-der-energiekondensation" tabindex="-1">3.2 Zweites Reich: Reich der Energiekondensation <a class="header-anchor" href="#_3-2-zweites-reich-reich-der-energiekondensation" aria-label="Permalink to &quot;3.2 Zweites Reich: Reich der Energiekondensation&quot;">​</a></h3><p>Der Kern des Reichs der Energiekondensation ist die &quot;Kondensation&quot;. Die Standards für das Erreichen des Reichs der Energiekondensation umfassen:</p><ul><li>Kann kosmische Energie stabil absorbieren und im Körper als nutzbare Energiereserve kondensieren</li><li>Baut ein grundlegendes Innenkreislaufsystem auf, Energie kann im Körper auf bestimmten Wegen zirkulieren</li><li>Kann die kondensierte Energie für grundlegende Angriffs-Verteidigungs- oder Hilfsanwendungen verwenden</li><li>Die Reinheit der Energie erreicht den Grundstandard, enthält keine übermäßigen Verunreinigungen</li></ul><p>Die Kultivierenden des Reichs der Energiekondensation haben bereits die grundlegende Identität als Kultivierende und können an einigen niedrigstufigen Kultivierungsaufgaben und sozialen Diensten teilnehmen. Der Durchbruch des Reichs der Energiekondensation erfordert in der Regel einige Monate bis einige Jahre Kultivierung.</p><h3 id="_3-3-drittes-reich-reich-der-energietransformation" tabindex="-1">3.3 Drittes Reich: Reich der Energietransformation <a class="header-anchor" href="#_3-3-drittes-reich-reich-der-energietransformation" aria-label="Permalink to &quot;3.3 Drittes Reich: Reich der Energietransformation&quot;">​</a></h3><p>Der Kern des Reichs der Energietransformation ist die &quot;Transformation&quot;. Die Standards für das Erreichen des Reichs der Energietransformation umfassen:</p><ul><li>Die Energienreinigung erreicht ein hohes Niveau, kann eine Art Energie in eine andere Art Energie umwandeln</li><li>Kann eine anfängliche Interaktion zwischen Energie und Materie durchführen (wie Energie an Objekte anhängen, Energie formen usw.)</li><li>Der Innenkreislauf ist stabil und effizient, die Energiewiederherstellungsgeschwindigkeit erhöht sich erheblich</li><li>Beginnt, die Existenz und das Funktionieren der Gesetze wahrzunehmen</li></ul><p>Die Kultivierenden des Reichs der Energietransformation sind die Rückgratskraft in der Gesellschaft und können Positionen wie mittlere Ausbilder, Techniker, Basismanager usw. übernehmen. Der Durchbruch des Reichs der Energietransformation erfordert in der Regel einige Jahre bis mehr als ein Jahrzehnt Kultivierung.</p><h3 id="_3-4-viertes-reich-reich-der-rechtsenergie" tabindex="-1">3.4 Viertes Reich: Reich der Rechtsenergie <a class="header-anchor" href="#_3-4-viertes-reich-reich-der-rechtsenergie" aria-label="Permalink to &quot;3.4 Viertes Reich: Reich der Rechtsenergie&quot;">​</a></h3><p>Der Kern des Reichs der Rechtsenergie ist das &quot;Gesetz&quot;. Die Standards für das Erreichen des Reichs der Rechtsenergie umfassen:</p><ul><li>Kann die grundlegenden Gesetze eines bestimmten Bereichs verstehen und anfänglich steuern</li><li>Energie und Gesetze verschmelzen zunächst und erzeugen die höherstufige Energieform namens &quot;Rechtskraft&quot;</li><li>Kann gesetzbasierte Techniken und Fähigkeiten ausführen</li><li>Die Bewusstseinsstärke erhöht sich erheblich, kann lange Zeit tiefe Deduktion und Meditation durchführen</li></ul><p>Die Kultivierenden des Reichs der Rechtsenergie sind hochstufige Talente in der Gesellschaft und können Positionen wie fortgeschrittene Ausbilder, technische Experten, mittlere Manager usw. übernehmen. Der Durchbruch des Reichs der Rechtsenergie erfordert in der Regel mehr als ein Jahrzehnt bis einige Jahrzehnte Kultivierung und ist der erste große Engpass im Leben vieler Kultivierender.</p><h3 id="_3-5-funftes-reich-reich-der-dao-energie" tabindex="-1">3.5 Fünftes Reich: Reich der Dao-Energie <a class="header-anchor" href="#_3-5-funftes-reich-reich-der-dao-energie" aria-label="Permalink to &quot;3.5 Fünftes Reich: Reich der Dao-Energie&quot;">​</a></h3><p>Der Kern des Reichs der Dao-Energie ist das &quot;Erreichen des Dao&quot;. Die Standards für das Erreichen des Reichs der Dao-Energie umfassen:</p><ul><li>Hat ein systematisches und tiefes Verständnis für die Gesetze eines bestimmten Bereichs, bildet einen persönlich einzigartigen &quot;Dao&quot;</li><li>Der persönliche Dao resoniert mit den kosmischen Gesetzen, kann die Gesetzeskraft in einem weiten Bereich mobilisieren</li><li>Energie und Gesetze verschmelzen tief, jede Geste enthält Gesetzeskraft</li><li>Das Bewusstsein entwickelt sich zu einem hohen Niveau, kann bewusstseinsmäßige Wahrnehmung zwischen Ebenen durchführen</li></ul><p>Die Kultivierenden des Reichs der Dao-Energie sind die &quot;Meister&quot; der Zivilisation, haben Autorität in ihren jeweiligen Bereichen und können Positionen wie zivilisationsweite Berater, Großausbilder, hochstufige Manager usw. übernehmen. Der Durchbruch des Reichs der Dao-Energie erfordert extrem hohes Talent und Verständnis, und viele Kultivierende erreichen ihn nicht ein Leben lang.</p><h3 id="_3-6-sechstes-reich-reich-der-vereinigung-mit-dem-dao" tabindex="-1">3.6 Sechstes Reich: Reich der Vereinigung mit dem Dao <a class="header-anchor" href="#_3-6-sechstes-reich-reich-der-vereinigung-mit-dem-dao" aria-label="Permalink to &quot;3.6 Sechstes Reich: Reich der Vereinigung mit dem Dao&quot;">​</a></h3><p>Der Kern des Reichs der Vereinigung mit dem Dao ist die &quot;Vereinigung mit dem Dao&quot;. Die Standards für das Erreichen des Reichs der Vereinigung mit dem Dao umfassen:</p><ul><li>Der persönliche Dao und die ursprünglichen Gesetze des Universums verschmelzen tief und erreichen den Zustand der &quot;Vereinigung von Himmel und Mensch&quot;</li><li>Kann die Funktionsweise lokaler Gesetze in einem weiten Bereich umschreiben</li><li>Die Lebensform beginnt sich zu einer höheren Dimension zu entwickeln und befreit sich teilweise von den Einschränkungen des materiellen Körpers</li><li>Kann einen stabilen persönlichen Bereich (Gesetzesbereich) schaffen</li></ul><p>Die Kultivierenden des Reichs der Vereinigung mit dem Dao sind die &quot;Großmeister&quot; der Zivilisation, sind die Spitzenfiguren in jedem Bereich und haben einen wichtigen Einfluss auf die Entwicklungsrichtung der Zivilisation. Der Durchbruch des Reichs der Vereinigung mit dem Dao ist ein kosmisches Ereignis und erfordert die Zusammenarbeit von Zeit, Ort und Menschen.</p><h3 id="_3-7-siebtes-reich-reich-der-grenzuberschreitung" tabindex="-1">3.7 Siebtes Reich: Reich der Grenzüberschreitung <a class="header-anchor" href="#_3-7-siebtes-reich-reich-der-grenzuberschreitung" aria-label="Permalink to &quot;3.7 Siebtes Reich: Reich der Grenzüberschreitung&quot;">​</a></h3><p>Der Kern des Reichs der Grenzüberschreitung ist die &quot;Grenzüberschreitung&quot;. Die Standards für das Erreichen des Reichs der Grenzüberschreitung umfassen:</p><ul><li>Kann die Grenzen der Ebenengesetze durchbrechen und ohne Unterstützung von Ankern eine Durchquerung zwischen Ebenen durchführen</li><li>Kann an der Ebenenmembran operieren, wie das Öffnen von Ebenenkanälen, das Reparieren von Ebenenrissen usw.</li><li>Der persönliche Bereich kann zu einem kleinen unabhängigen Raum erweitert werden</li><li>Die Lebensform wird weiter hochdimensional und kann in den Gesetzsumgebungen verschiedener Ebenen überleben</li></ul><p>Die Mächtigen des Reichs der Grenzüberschreitung sind Existenzen auf &quot;Ebenenniveau&quot; und können unabhängig Aufgaben und Verantwortlichkeiten auf Ebenenniveau übernehmen. Der Durchbruch des Reichs der Grenzüberschreitung ist extrem schwierig, und die Anzahl der Kultivierenden, die dieses Reich im gesamten Heng Yuan Zhou erreichen, ist begrenzt.</p><h3 id="_3-8-achtes-reich-reich-der-schopfung" tabindex="-1">3.8 Achtes Reich: Reich der Schöpfung <a class="header-anchor" href="#_3-8-achtes-reich-reich-der-schopfung" aria-label="Permalink to &quot;3.8 Achtes Reich: Reich der Schöpfung&quot;">​</a></h3><p>Der Kern des Reichs der Schöpfung ist die &quot;Schöpfung&quot;. Die Standards für das Erreichen des Reichs der Schöpfung umfassen:</p><ul><li>Kann vollständige Welten in isolierten Räumen schaffen, einschließlich Materie, Energie, Gesetze und Leben</li><li>Kann das grundlegende Gesetzessystem der neuen Welt entwerfen und festlegen</li><li>Der persönliche Bereich kann zu einer vollständigen Welt erweitert werden</li><li>Die Lebensform nähert sich einer hochdimensionalen Existenz und kann gleichzeitig in mehreren Ebenen erscheinen</li></ul><p>Die Mächtigen des Reichs der Schöpfung sind Existenzen auf &quot;Weltniveau&quot;, und die von ihnen geschaffenen Welten können als Kultivierungsressourcen, Experimentierorte, Zivilisationsunterkünfte usw. verwendet werden. Der Durchbruch des Reichs der Schöpfung ist eines der seltensten Ereignisse im Universum.</p><h3 id="_3-9-neuntes-reich-reich-des-ursprungs" tabindex="-1">3.9 Neuntes Reich: Reich des Ursprungs <a class="header-anchor" href="#_3-9-neuntes-reich-reich-des-ursprungs" aria-label="Permalink to &quot;3.9 Neuntes Reich: Reich des Ursprungs&quot;">​</a></h3><p>Der Kern des Reichs des Ursprungs ist der &quot;Ursprung&quot;. Die Standards für das Erreichen des Reichs des Ursprungs umfassen:</p><ul><li>Berührt die ursprünglichen Gesetze des Universums, kann die ultimativen Funktionsregeln des Universums verstehen</li><li>Kann an der Feinabstimmung und Optimierung der kosmischen Gesetze teilnehmen und die Evolutionsrichtung des Universums beeinflussen</li><li>Die Lebensform stellt eine tiefe Verbindung mit dem Ursprung des Universums her und ist fast unsterblich</li><li>Kann die Ursprungskraft auf kosmischer Skala mobilisieren</li></ul><p>Die Mächtigen des Reichs des Ursprungs sind Existenzen auf &quot;kosmischem Niveau&quot; und die höchste Kraft im Heng Yuan Zhou. Die Kultivierenden, die das Reich des Ursprungs erreichen, werden gewöhnlich als &quot;höchste Mächtige der Ebene&quot; bezeichnet und sind die Kernzielgruppe der &quot;20%-Aktivierungsstrategie&quot; der symbiotischen Zivilisation.</p><h2 id="iv-mechanismus-der-reichszertifizierung" tabindex="-1">IV. Mechanismus der Reichszertifizierung <a class="header-anchor" href="#iv-mechanismus-der-reichszertifizierung" aria-label="Permalink to &quot;IV. Mechanismus der Reichszertifizierung&quot;">​</a></h2><p>Um die Gerechtigkeit und Genauigkeit der Reichsbewertung zu gewährleisten, hat die symbiotische Zivilisation einen strengen Mechanismus der Reichszertifizierung eingerichtet:</p><ol><li><strong>Automatische Ankerüberwachung</strong>: Nachdem der Kultivierende eine Verbindung zum Ankernetzwerk hergestellt hat, überwacht der Anker kontinuierlich Indikatoren wie sein Energieniveau, sein Gesetzesverständnis und seine Bewusstseinsstärke, und wenn die Indikatoren den Standard eines neuen Reichs erreichen, warnt er automatisch</li><li><strong>Prüfung durch das Standardkomitee</strong>: Für den Durchbruch von Reichen ab dem Vierten Reich muss das Komitee für Kultivierungsstandards eine formelle Prüfung organisieren, die drei Aspekte umfasst: Theorietest, Praxistest und Beitragsbewertung</li><li><strong>Öffentliche Bekanntmachung und Einspruchsfrist</strong>: Nach Bestehen der Prüfung erfolgt eine dreißigtägige öffentliche Bekanntmachung; während der Bekanntmachungsfrist kann jedes Leben Einspruch erheben, und wenn der Einspruch begründet ist, muss eine erneute Prüfung erfolgen</li><li><strong>Verleihung des Reichszertifikats</strong>: Nach der öffentlichen Bekanntmachung ohne Einspruch verleiht das Ankernetzwerk ein einheitliches Reichszertifikat, und die Zertifikatsinformationen werden in die Zivilisationsdatenbank aufgenommen</li></ol><h2 id="v-entsprechung-zwischen-reichen-und-sozialen-rechten-pflichten" tabindex="-1">V. Entsprechung zwischen Reichen und sozialen Rechten-Pflichten <a class="header-anchor" href="#v-entsprechung-zwischen-reichen-und-sozialen-rechten-pflichten" aria-label="Permalink to &quot;V. Entsprechung zwischen Reichen und sozialen Rechten-Pflichten&quot;">​</a></h2><p>Kultivierende verschiedener Reiche genießen in der symbiotischen Zivilisation unterschiedliche Rechte und übernehmen unterschiedliche Pflichten:</p><table tabindex="0"><thead><tr><th>Reich</th><th>Kernrechte</th><th>Kernpflichten</th></tr></thead><tbody><tr><td>Energiewahrnehmung - Energiekondensation</td><td>Kostenloser Erhalt grundlegender Kultivierungsressourcen, Nutzungsrecht an öffentlichen Kultivierungsplätzen</td><td>Einhaltung der Kultivierungsethik, Teilnahme an grundlegenden Gemeindediensten</td></tr><tr><td>Energietransformation - Rechtsenergie</td><td>Recht auf Zuteilung fortgeschrittener Ressourcen, Recht auf Beantragung der Ausbilderqualifikation, Recht auf regionsübergreifende Mobilität</td><td>Anleitung anfänglicher Kultivierender, Teilnahme an technischer Forschung und Entwicklung oder sozialen Diensten</td></tr><tr><td>Dao-Energie - Vereinigung mit dem Dao</td><td>Recht auf Zuteilung hochstufiger Ressourcen, Recht auf hochstufigen Zugang zu Ankern, Recht auf Teilnahme an zivilisationsweiten Entscheidungen</td><td>Übernahme von zivilisationsweiten Forschungsprojekten, Aufrechterhaltung der Stabilität regionaler Anker</td></tr><tr><td>Grenzüberschreitung - Schöpfung</td><td>Recht auf Zuteilung von Ressourcen auf Ebenenniveau, Recht auf Schaffung unabhängiger Räume, Recht auf Teilnahme an Angelegenheiten der Ebene</td><td>Übernahme von Aufgaben auf Ebenenniveau, Aufrechterhaltung der Stabilität der Ebenenmembran, Teilnahme an Angelegenheiten zwischen Ebenen</td></tr><tr><td>Ursprung</td><td>Recht auf Zuteilung von Ressourcen auf kosmischem Niveau, Recht auf Teilnahme an der Feinabstimmung der Gesetze, Recht auf Teilnahme an den höchsten Entscheidungen der Zivilisation</td><td>Aufrechterhaltung der overallen Stabilität des Universums, Anleitung der Evolutionsrichtung der Zivilisation, Ausbildung von Nachwuchstalenten</td></tr></tbody></table><h2 id="schlusswort" tabindex="-1">Schlusswort <a class="header-anchor" href="#schlusswort" aria-label="Permalink to &quot;Schlusswort&quot;">​</a></h2><p>Der Standard für die einheitliche Einteilung der Kultivierungsreiche ist eine der Infrastrukturen des Kultivierungssystems der Anker-Symbiotischen Zivilisation. Er bietet den dreihundert Kultivierungssystemen ein gemeinsames &quot;Maßsystem&quot;, ermöglicht den systemübergreifenden Austausch, die Zusammenarbeit und den Wettbewerb und bietet gleichzeitig eine objektive Grundlage für die Ressourcenallokation, die soziale Governance und die Talentausbildung. Die Einteilung der neun Reiche dient nicht dazu, Klassenunterschiede zu schaffen, sondern die Evolutionsstufe jedes Kultivierenden klar zu kennzeichnen und ihm die am besten geeignete Unterstützung und Anleitung zu bieten. Die Erhöhung des Reichs ist nicht das Ende, sondern ein neuer Ausgangspunkt für eine höherstufige symbiotische Evolution.</p><h2 id="zugehorige-dokumente" tabindex="-1">Zugehörige Dokumente <a class="header-anchor" href="#zugehorige-dokumente" aria-label="Permalink to &quot;Zugehörige Dokumente&quot;">​</a></h2><ul><li>10-三百套本源修炼体系总览 (Gesamtübersicht der Dreihundert Ursprungs-Kultivierungssysteme)</li><li>17-位面至高强者标准 (Standard der höchsten Mächtigen der Ebene)</li><li>29-共生度评估体系 (System zur Bewertung des Grades der Symbiose)</li></ul>',57)])])}const m=n(s,[["render",d]]);export{o as __pageData,m as default};
